| {
      type: 'host_send_message_request';
      /** Engine-minted correlation id. Measured: the binary mints `hsm-<n>`; the fixture uses `call-send-001`. NEVER assume a format, and keep it in its own namespace - it is NOT a tool call_id. */
      call_id: string;
      /** Engine platform vocabulary, NOT a Darhai plugin id. Measured from the bundled v0.12.26 `send_message` tool description: telegram, discord, slack, whatsapp, signal, bluebubbles, qqbot, matrix, mattermost, homeassistant, dingtalk, feishu, wecom, wecom_callback, weixin, email, sms. Schema declares a bare string, so treat unknown values as data. */
      platform: string;
      body: string;
      /** Absent means "use the host's default channel for this platform" (engine's own tool doc). */
      chat_id?: string;
      thread_id?: string;
      /** Email subject line. */
      subject?: string;
      conversation_id?: string;
    }

| { type: 'provider_failover_receipt'; receipt: ProviderFailoverReceipt }

// Supporting types (all exported from protocol.ts, all field names and enum
// members taken verbatim from schema/core-event.schema.json):

/** Shared by `receipt.reason`, `candidate.failure_reason`, `candidate.cooldown_reason`. */
export type ProviderFailureReason =
  | 'auth'
  | 'auth_permanent'
  | 'format'
  | 'rate_limit'
  | 'overloaded'
  | 'billing'
  | 'timeout'
  | 'model_not_found'
  | 'session_expired'
  | 'context_overflow'
  | 'unknown';

export type FailoverRejectReason =
  | 'provider_not_allowed'
  | 'provider_denied'
  | 'region_not_allowed'
  | 'organization_mismatch'
  | 'tools_unsupported'
  | 'vision_unsupported'
  | 'structured_output_unsupported'
  | 'context_window_unknown'
  | 'context_window_too_small'
  | 'pricing_stale'
  | 'pricing_unavailable'
  | 'cooldown_active'
  | 'budget_denied';

/** Rust `Result` serialized externally-tagged; exactly one key is present. */
export type FailoverDisposition = { Ok: null } | { Err: FailoverRejectReason };

export type FailoverPricing = {
  source: string;
  age_seconds: number | null;
  stale: boolean;
  priced: boolean;
  estimated_microcents: number | null;
};

export type FailoverCandidate = {
  provider: string;
  model: string;
  region: string | null;
  disposition: FailoverDisposition;
  failure_reason: ProviderFailureReason | null;
  cooldown_reason: ProviderFailureReason | null;
  retry_after_ms: number | null;
  pricing: FailoverPricing;
};

export type ProviderFailoverReceipt = {
  reason: ProviderFailureReason;
  failed_provider: string;
  failed_model: string;
  candidates: FailoverCandidate[];
  /** null = no candidate survived; the turn is about to fail. Distinct from absent. */
  selected_provider: string | null;
  selected_model: string | null;
};

| {
      type: 'unknown_tool_effect_resolved';
      recovery_version: 1;
      session_id: string;
      turn_id: string;
      cursor: RecoveryCursor;
      tool_execution_id: string;
      outcome: UnknownToolEffectOutcome;
      operator_id: string;
      evidence: ToolEffectEvidence;
    }

// Supporting types (shared with the resolve_unknown_tool_effect command; if
// the turn_recovery capability already declares RecoveryCursor, import it
// rather than declaring a second copy):

export type RecoveryCursor = {
  /** Schema pattern ^[0-9a-f]{64}$ - bare hex, NO `sha256:` prefix. */
  journal_digest: string;
  /** Optional: only `journal_digest` is in the schema's `required` list. */
  journal_sequence?: number;
};

export type ToolEffectEvidenceSource =
  | 'tool_receipt'
  | 'provider_receipt'
  | 'process_observation'
  | 'external_system_record';

export type ToolEffectEvidence = {
  source: ToolEffectEvidenceSource;
  /** minLength 1, maxLength 256. */
  reference_id: string;
  /** minimum 1. */
  observed_at_unix_ms: number;
  /** Schema pattern ^sha256:[0-9a-f]{64}$ - prefixed, unlike journal_digest. */
  digest: string;
};

export type UnknownToolEffectOutcome = 'succeeded' | 'failed' | 'not_started';

| {
      type: 'host_send_message_result';
      /** Must echo the request's call_id verbatim. */
      call_id: string;
      ok: boolean;
      /** Platform message id on success. Optional in the schema; the contract example sends it. */
      message_id?: string;
      /** Failure text. Optional in the schema; the contract example sends `""` on success. */
      error?: string;
    }

| {
      type: 'resolve_unknown_tool_effect';
      recovery_version: 1;
      session_id: string;
      turn_id: string;
      cursor: RecoveryCursor;
      tool_execution_id: string;
      outcome: UnknownToolEffectOutcome;
      operator_id: string;
      evidence: ToolEffectEvidence;
    }
